import { expect, test, uniqueName } from "../../fixtures";

const TAG = "@REV-05";

const futureYear = new Date().getFullYear() + 2;
const insuranceText = `Insurer: Harbor Mutual
Policy Number: HM-55-1290
Coverage Amount: $2,000,000
Expiry Date: ${futureYear}-12-31
`;
const w9Text = `Legal Name: Acme Freight LLC
Tax ID: 12-3456789
Business Type: LLC
`;
const contractText = `Counterparty: Acme Freight LLC
Effective Date: 2026-01-01
Expiry Date: ${futureYear + 1}-12-31
`;

test("approving every extraction approves the vendor", { tag: TAG }, async ({ apiAs }) => {
  // Arrange: a vendor in review with three pending extractions
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  const createRes = await member.post(`/api/vendors`, {
    data: { name: uniqueName("Review Co"), category: "logistics", contact_email: "ops@acme.example" },
  });
  expect(createRes.status(), await createRes.text()).toBe(201);
  const vendor = await createRes.json();

  const uploads: Array<[string, string, string]> = [
    ["w9", "w9.txt", w9Text],
    ["insurance_certificate", "insurance.txt", insuranceText],
    ["contract", "contract.txt", contractText],
  ];
  for (const [kind, filename, text] of uploads) {
    const up = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: { kind, file: { name: filename, mimeType: "text/plain", buffer: Buffer.from(text) } },
    });
    expect(up.status(), await up.text()).toBe(201);
  }

  // Wait for background extraction of every document.
  await expect
    .poll(
      async () => {
        const docs = await (await member.get(`/api/vendors/${vendor.id}/documents`)).json();
        return docs.map((d: { status: string }) => d.status);
      },
      { timeout: 60_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);

  const submitRes = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitRes.status(), await submitRes.text()).toBe(200);

  const docs = await (await member.get(`/api/vendors/${vendor.id}/documents`)).json();
  const extractionIds: string[] = [];
  for (const doc of docs) {
    const exRes = await member.get(`/api/documents/${doc.id}/extraction`);
    expect(exRes.status(), await exRes.text()).toBe(200);
    const ex = await exRes.json();
    expect(ex.status, await exRes.text()).toBe("pending_review");
    extractionIds.push(ex.id);
  }
  expect(extractionIds).toHaveLength(3);

  // Act: reviewer approves all three extractions
  for (const id of extractionIds) {
    const decRes = await reviewer.post(`/api/extractions/${id}/decision`, {
      data: { decision: "approve" },
    });
    expect(decRes.status(), await decRes.text()).toBe(200);
  }

  // Assert: vendor is approved and the audit event is recorded
  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendor.id}`);
      return (await res.json()).status;
    }, { timeout: 30_000 })
    .toBe("approved");

  await expect
    .poll(async () => {
      const res = await reviewer.get(`/api/vendors/${vendor.id}/audit`);
      const trail = await res.json();
      return trail.items.map((e: { action: string }) => e.action);
    }, { timeout: 30_000 })
    .toContain("vendor.approved");
});
